// _shared/ingredients.ts
export function parseIngredient(line: string) {
  const fractions: Record<string, string> = {
    "½": "1/2",
    "¼": "1/4",
    "¾": "3/4",
    "⅓": "1/3",
    "⅔": "2/3",
  };
  const normalized = line
    .replace(
      /[½¼¾⅓⅔]/g,
      (c, index, text) =>
        (index > 0 && /\d/.test(text[index - 1]) ? " " : "") + fractions[c],
    )
    .trim();
  const taste = normalized.match(/^(.+?)\s+за\s+смаком\.?$/i);
  if (taste)
    return {
      name: taste[1].trim(),
      quantity: null,
      unit: "за смаком",
      category: groceryCategory(taste[1]),
      price: null,
      note: line,
    };
  if (
    /^\s*\d+(?:[.,]\d+)?\s*(?:ст\.?\s*(?:л\.?|лож(?:ка|ки|ек))|ч\.?\s*(?:л\.?|лож(?:ка|ки|ек)))/i.test(
      normalized,
    )
  )
    return {
      name: line.trim().slice(0, 160),
      quantity: null,
      unit: "за рецептом",
      category: groceryCategory(line),
      price: null,
      note: line,
    };
  const match =
    normalized.match(
      /^(\d+(?:[.,]\d+)?(?:\s+\d+\/\d+)?|\d+\/\d+)\s*(кг|kg|гр?\.?|g|л|l|мл|ml|шт\.?|pcs|cups?|tbsp|tsp|ст\.?\s*л\.?|ч\.?\s*л\.?)?\s+(.+)$/i,
    ) ??
    normalized
      .match(
        /^(.+?)\s*[-—–:]\s*(\d+(?:[.,]\d+)?)\s*(кг|kg|г|g|л|l|мл|ml|шт\.?|pcs)?$/i,
      )
      ?.map((v, i, a) =>
        i === 1 ? a[2] : i === 2 ? a[3] || "" : i === 3 ? a[1] : v,
      );
  if (!match)
    return {
      name: line.trim().slice(0, 160),
      quantity: null,
      unit: "за рецептом",
      category: groceryCategory(line),
      price: null,
      note: line,
    };
  const amount = match[1]
    .replace(",", ".")
    .split(/\s+/)
    .reduce((sum, v) => {
      const parts = v.split("/").map(Number);
      return (
        sum + (parts.length === 2 && parts[1] ? parts[0] / parts[1] : parts[0])
      );
    }, 0);
  const unit =
    (
      {
        kg: "кг",
        g: "г",
        гр: "г",
        "гр.": "г",
        l: "л",
        ml: "мл",
        pcs: "шт.",
        шт: "шт.",
        "шт.": "шт.",
      } as Record<string, string>
    )[(match[2] || "").toLowerCase()] ||
    match[2] ||
    "шт.";
  const supported = ["кг", "г", "л", "мл", "шт."].includes(unit);
  return {
    name: (supported ? match[3] : line)
      .trim()
      .replace(/[;,.]+$/, "")
      .slice(0, 160),
    quantity:
      supported && Number.isFinite(amount) && amount > 0 && amount < 1000000
        ? Math.round(amount * 1000) / 1000
        : null,
    unit: supported ? unit : "за рецептом",
    category: groceryCategory(match[3]),
    price: null,
    note: line,
  };
}

// _shared/urls.ts
export function publicUrl(input: string, base?: string): string {
  try {
    const u = new URL(input, base);
    const h = u.hostname.toLowerCase().replace(/\.$/, "");
    if (
      u.protocol !== "https:" ||
      u.username ||
      u.password ||
      (u.port && u.port !== "443") ||
      h.length > 253 ||
      !h.includes(".") ||
      h.includes(":") ||
      h.startsWith("[") ||
      /^\d+(?:\.\d+)*$/.test(h) ||
      /(?:^|\.)(?:localhost|local|internal|lan|home|test|invalid|onion)$/.test(
        h,
      )
    )
      return "";
    u.hostname = h;
    u.hash = "";
    return u.href.length <= 2048 ? u.href : "";
  } catch {
    return "";
  }
}

function stripTrailingPunctuation(raw: string): string {
  let cleaned = raw.replace(/[.,!?;:»"'…]+$/, "");
  while (cleaned.endsWith(")")) {
    const opens = (cleaned.match(/\(/g) || []).length;
    const closes = (cleaned.match(/\)/g) || []).length;
    if (closes > opens) cleaned = cleaned.slice(0, -1);
    else break;
  }
  return cleaned;
}

/** Normalize user-pasted link or share text (e.g. bare vt.tiktok.com/ZSpVxxHh1/) into HTTPS URL. */
export function normalizeImportUrl(raw: string): string {
  const trimmed = raw.trim();
  if (!trimmed) return "";
  const httpsMatch = trimmed.match(/https:\/\/[^\s<>"{}|\\^`[\]]+/i);
  if (httpsMatch) {
    const valid = publicUrl(stripTrailingPunctuation(httpsMatch[0]));
    if (valid) return valid;
  }
  if (!/\b[a-z][a-z0-9+.-]*:\/\//i.test(trimmed)) {
    const bareMatch = trimmed.match(
      /(?:^|[\s(])((?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}(?:[/?#][^\s<>"{}|\\^`[\]]*)?)/i,
    );
    if (bareMatch) {
      const cleaned = stripTrailingPunctuation(bareMatch[1]);
      const valid = publicUrl(`https://${cleaned}`);
      if (valid) return valid;
    }
  }
  return trimmed;
}

